-- Vocabulary starter decks: shared word lists by CEFR level and topic.
-- ============================================================================
-- 24 decks (A1 5, A2 5, B1 5, B2 5, C1 4), 288 words.
-- Each word has a learner-friendly definition in simple English, a natural
-- example sentence, and Russian and Uzbek (Latin script) translations.
-- Uzbek uses U+02BB for oʻ / gʻ and U+02BC for the tutuq belgisi (maʼruza).
--
-- Every deck is registered as a 'vocabulary.deck' learning item so it appears
-- in the skill library and the Today planner. Idempotent: decks and words are
-- upserted, and words no longer in a seeded deck are removed.
-- Generated from a reviewed source list; edit the list, then regenerate.
-- ============================================================================

do $$
declare
  v_en_id uuid;
  v_vocab_product_id uuid;
begin
  select id into v_en_id from public.languages where code = 'en' limit 1;
  if v_en_id is null then
    raise exception 'language en not found; seed languages first';
  end if;

  select p.id into v_vocab_product_id
  from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-vocabulary'
  order by p.created_at asc
  limit 1;
  if v_vocab_product_id is null then
    raise exception 'english-vocabulary product not found; seed product first';
  end if;

  select v_vocab_product_id, v_en_id, d.slug, d.title, d.level, d.topic, d.description, 'published', d.sort_order,
    jsonb_build_object('seeded_by', '20261022172000_english_vocabulary_deck_content')
  from (values
      ('a1-family', 'Family', 'A1', 'family', 'Words for the people in your family.', 10),
      ('a1-food-and-drink', 'Food and drink', 'A1', 'food', 'Everyday food, drinks and meals.', 20),
      ('a1-at-home', 'At home', 'A1', 'home', 'Rooms and things in your home.', 30),
      ('a1-in-the-city', 'In the city', 'A1', 'city', 'Places you visit in a town or city.', 40),
      ('a1-daily-routine', 'My day', 'A1', 'daily routine', 'Things you do every day, from morning to night.', 50),
      ('a2-shopping', 'Shopping', 'A2', 'shopping', 'Prices, paying and trying things on.', 60),
      ('a2-weather', 'The weather', 'A2', 'weather', 'Talk about sun, rain, snow and the forecast.', 70),
      ('a2-travel', 'Travel', 'A2', 'travel', 'Tickets, hotels and getting from place to place.', 80),
      ('a2-at-work', 'At work', 'A2', 'work', 'Basic words for jobs and the workplace.', 90),
      ('a2-free-time', 'Free time', 'A2', 'free time', 'Hobbies, sport and weekends.', 100),
      ('b1-feelings', 'Feelings', 'B1', 'emotions', 'Describe how you and other people feel.', 110),
      ('b1-study', 'Study and education', 'B1', 'education', 'Words for school, college and university life.', 120),
      ('b1-technology', 'Technology', 'B1', 'technology', 'Phones, apps and the internet.', 130),
      ('b1-health', 'Health', 'B1', 'health', 'Talk about feeling ill and getting better.', 140),
      ('b1-environment', 'The environment', 'B1', 'environment', 'Nature, pollution and saving resources.', 150),
      ('b2-money', 'Money and finance', 'B2', 'money', 'Budgets, loans, savings and bills.', 160),
      ('b2-news-and-media', 'News and media', 'B2', 'media', 'Read the news carefully and talk about it.', 170),
      ('b2-career', 'Work and career', 'B2', 'career', 'Applying for jobs and moving up at work.', 180),
      ('b2-personality', 'Personality', 'B2', 'personality', 'Describe what people are like.', 190),
      ('b2-housing', 'Housing and city life', 'B2', 'housing', 'Renting a flat and living in a busy city.', 200),
      ('c1-academic-verbs', 'Academic verbs', 'C1', 'academic', 'Verbs for essays, reports and presentations.', 210),
      ('c1-argument', 'Argument and persuasion', 'C1', 'persuasion', 'Make, support and answer arguments.', 220),
      ('c1-abstract-nouns', 'Abstract nouns', 'C1', 'abstract nouns', 'Nouns for ideas, qualities and processes.', 230),
      ('c1-collocations', 'Key collocations', 'C1', 'collocations', 'Natural word partners for formal speaking and writing.', 240)
  ) as d(slug, title, level, topic, description, sort_order)
  on conflict (language_id, slug) do update
  set
    product_id = excluded.product_id,
    title = excluded.title,
    level = excluded.level,
    topic = excluded.topic,
    description = excluded.description,
    status = excluded.status,
    sort_order = excluded.sort_order,
    metadata = coalesce(public.vocabulary_decks.metadata, '{}'::jsonb) || excluded.metadata,
    updated_at = now();

  create temporary table tmp_vocabulary_seed_words (
    slug text not null,
    sort_order integer not null,
    word text not null,
    part_of_speech text,
    definition text not null,
    example text,
    translation_ru text,
    translation_uz text
  ) on commit drop;


  select d.id, w.word, w.part_of_speech, w.definition, w.example, w.translation_ru, w.translation_uz, w.sort_order
  from tmp_vocabulary_seed_words w
  join public.vocabulary_decks d on d.language_id = v_en_id and d.slug = w.slug
  on conflict (deck_id, word) do update
  set
    part_of_speech = excluded.part_of_speech,
    definition = excluded.definition,
    example = excluded.example,
    translation_ru = excluded.translation_ru,
    translation_uz = excluded.translation_uz,
    sort_order = excluded.sort_order,
    updated_at = now();

  delete from public.vocabulary_deck_words vw
  using public.vocabulary_decks d
  where vw.deck_id = d.id
    and d.language_id = v_en_id
    and d.slug in (select distinct slug from tmp_vocabulary_seed_words)
    and not exists (
      select 1 from tmp_vocabulary_seed_words w where w.slug = d.slug and w.word = vw.word
    );
end
$$;

  product_id,
  language_id,
  service_key,
  content_type,
  source_table,
  source_record_id,
  source_ref,
  title,
  description,
  skill_key,
  subskill_keys,
  cefr_level,
  difficulty,
  estimated_minutes,
  learning_objective,
  tags,
  status,
  payload_json,
  metadata
)
select
  d.product_id,
  d.language_id,
  'vocabulary',
  'vocabulary.deck',
  'vocabulary_decks',
  d.id,
  d.slug,
  d.title,
  d.description,
  'vocabulary',
  array['vocabulary.recall', 'vocabulary.usage']::text[],
  d.level,
  case d.level
    when 'A1' then 0.20
    when 'A2' then 0.30
    when 'B1' then 0.45
    when 'B2' then 0.60
    when 'C1' then 0.75
    when 'C2' then 0.90
    else 0.50
  end,
  6,
  'Learn the words in this set, then match each meaning to the right word.',
  array[d.topic]::text[],
  'published',
  jsonb_build_object('topic', d.topic, 'word_count', (select count(*) from public.vocabulary_deck_words w where w.deck_id = d.id)),
  jsonb_build_object('seeded_by', '20261022172000_english_vocabulary_deck_content')
from public.vocabulary_decks d
where d.status = 'published'
  and d.metadata->>'seeded_by' = '20261022172000_english_vocabulary_deck_content'
on conflict (language_id, service_key, content_type, source_ref) do update
set
  product_id = excluded.product_id,
  source_table = excluded.source_table,
  source_record_id = excluded.source_record_id,
  title = excluded.title,
  description = excluded.description,
  skill_key = excluded.skill_key,
  subskill_keys = excluded.subskill_keys,
  cefr_level = excluded.cefr_level,
  difficulty = excluded.difficulty,
  estimated_minutes = excluded.estimated_minutes,
  learning_objective = excluded.learning_objective,
  tags = excluded.tags,
  status = excluded.status,
  payload_json = excluded.payload_json,
  metadata = coalesce(public.learning_content_registry_items.metadata, '{}'::jsonb) || excluded.metadata,
  updated_at = now();
